function bkChannelCard(ym) { const S = bkAllLines().filter(l => l.date.slice(0, 7) === ym), m = {}; S.forEach(l => { const ch = l.channel || bkChannelOf(l.desc, l); const o = m[ch] = m[ch] || { ch, n: 0, cr: 0, dr: 0, open: 0 }; o.n++; o.cr += l.cr; o.dr += l.dr; if (!['Reconciled', 'Matched', 'Approved', 'Interest', 'Bank Charges'].includes(l.status)) o.open++; }); const rows = Object.values(m).sort((x, y) => y.n - x.n); return card(`Transactions by channel · ${rmPeriodLabel(ym)} · all banks`, table('bkChan', [{ h: 'Channel', k: r => r.ch, t: 'text' }, { h: 'Lines', k: r => r.n, t: 'num' }, { h: 'Credits', k: r => r.cr, t: 'inr' }, { h: 'Debits', k: r => r.dr, t: 'inr' }, { h: 'Open', k: r => r.open, t: 'num', rc: r => r.open ? 'amber' : '' }, { h: 'Reconciled', k: r => PCT(r.n ? (r.n - r.open) / r.n * 100 : 100, 0), t: 'text' }], rows, { compact: true, empty: 'No statement lines in this period.', totalVals: [null, rows.reduce((s, r) => s + r.n, 0), rows.reduce((s, r) => s + r.cr, 0), rows.reduce((s, r) => s + r.dr, 0), rows.reduce((s, r) => s + r.open, 0), null] }), { right: exportBtns('bkChan', 'br_home') }); }
