Object.assign(BK_ACT, {
  bkFeeOpen: t => bkFeeDoc(t.dataset.k), bkBulkDoc: t => { App.ui.bkBulk = t.dataset.k; bkBulkDoc(t.dataset.k); },
  bkBulkMatch: async t => { const f = BKT().bulk.find(x => x.id === t.dataset.k); if (!f) return; const line = bkAllLines().find(l => l.id === f.line); if (!line || line.match) return toast('Bank debit not found or already matched.', 'bad'); if (bkPeriodLocked(f.bank, line.date)) return toast('Period is locked.', 'bad'); const B = bkBook(f.bank, bkStart(f.bank), PROC_TODAY).filter(b => f.books.includes(b.jid) && !b.recon); if (!B.length) return toast('The vouchers are already reconciled.', 'bad'); const tx = Store.clone(BKT()), ftx = Store.clone(FT()); const m = bkMakeMatch(tx, f.bank, [line], B, { kind: B.length > 1 ? '1:n' : '1:1', remarks: `Bulk ${f.kind.toLowerCase()} ${f.no} – ${f.beneficiaries.length} beneficiaries (${f.beneficiaries.filter(b => b.status === 'Success').length} success, ${f.beneficiaries.filter(b => /Failed|Rejected/.test(b.status)).length} failed / rejected, ${f.beneficiaries.filter(b => b.status === 'Pending').length} pending)`, ftx }); const bf = tx.bulk.find(x => x.id === f.id); bf.match = m.id; bf.status = m.pending ? 'Pending approval' : 'Reconciled'; await bkSaveAll(tx, ftx); audit('Bank Reconciliation', 'Bulk payment matched', { new: `${f.no} ↔ ${m.no} · ${INR(f.total)}`, approval: m.pending ? 'Pending' : 'Reconciled' }); closeModal(); toast(`${f.no} ${m.pending ? 'submitted for approval' : 'reconciled'} (${m.no}).`); },
  bkBulkTemplate: () => { if (!window.XLSX) return; const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Beneficiary', 'Account', 'IFSC', 'Amount', 'Status', 'UTR', 'Reason', 'Reference'], ['Abdul Rahman', 'XXXXXX1234', 'HDFC0001234', 42500, 'Success', 'SBINN26275123456789', '', 'PAYRUN-2026-09'], ['Mohd Arif', 'XXXXXX5678', 'UTIB0000455', 38000, 'Failed', '', 'Account closed', 'PAYRUN-2026-09']]), 'Status'); saveFile('MSEA_Bulk_Payment_Status_Template.xlsx', new Blob([XLSX.write(wb, { bookType: 'xlsx', type: 'array' })])); },
  bkBulkUpload: t => { const file = t.files[0]; if (!file) return; const id = t.dataset.k; const rd = new FileReader(); rd.onload = async () => { try { if (!window.XLSX) return; const wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' }), raw = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '', raw: false }); const norm = h => String(h).toLowerCase().replace(/[^a-z]/g, ''); const col = (o, ks) => { const k = Object.keys(o).find(h => ks.includes(norm(h))); return k ? o[k] : ''; }; const rows = raw.map(o => ({ name: String(col(o, ['beneficiary', 'beneficiaryname', 'name'])).trim(), acct: String(col(o, ['account', 'accountno', 'accountnumber'])).trim(), ifsc: String(col(o, ['ifsc', 'ifsccode'])).trim().toUpperCase(), amount: rmAmt(col(o, ['amount', 'amt'])), status: String(col(o, ['status', 'txnstatus'])).trim(), utr: String(col(o, ['utr', 'utrno', 'reference'])).trim(), reason: String(col(o, ['reason', 'remarks', 'failurereason'])).trim(), ref: String(col(o, ['reference', 'batchref', 'fileref'])).trim() })).filter(r => r.name && r.amount); if (!rows.length) return toast('No beneficiary rows found (expected Beneficiary, Account, IFSC, Amount, Status, UTR, Reason).', 'bad'); const tx = Store.clone(BKT()); let f = tx.bulk.find(x => x.id === id); if (!f || (rows[0].ref && f.ref !== rows[0].ref && tx.bulk.some(x => x.ref === rows[0].ref))) f = tx.bulk.find(x => x.ref === rows[0].ref) || f; if (!f) return toast('Select a bulk file first.', 'bad'); let upd = 0, added = 0; rows.forEach(r => { const st = /success|processed|credited|paid/i.test(r.status) ? 'Success' : /fail|return/i.test(r.status) ? 'Failed' : /reject/i.test(r.status) ? 'Rejected' : 'Pending'; const b = f.beneficiaries.find(x => bkNorm(x.name) === bkNorm(r.name) && x.amount === r.amount) || f.beneficiaries.find(x => bkNorm(x.name) === bkNorm(r.name)); if (b) { b.status = st; b.utr = r.utr || b.utr; b.reason = r.reason; if (r.acct) b.acct = r.acct; if (r.ifsc) b.ifsc = r.ifsc; upd++; } else { f.beneficiaries.push({ name: r.name, acct: r.acct, ifsc: r.ifsc, amount: r.amount, status: st, utr: r.utr, reason: r.reason }); added++; } }); f.statusFile = file.name; f.statusAt = nowIso(); f.statusBy = App.user.name; await bkSaveAll(tx); audit('Bank Reconciliation', 'Bulk payment status file imported', { new: `${f.no} · ${file.name} · ${upd} updated, ${added} added`, approval: '' }); toast(`${file.name}: ${upd} beneficiaries updated, ${added} added.`); } catch (e) { console.error(e); toast('Could not read the status file: ' + e.message, 'bad'); } }; rd.readAsArrayBuffer(file); t.value = ''; },
  bkCertGen: () => { const gl = bkGl(), ym = bkPeriodYm(); if (bkCertFor(gl, ym)) return toast('Certificate already generated.', 'bad'); askReason(`Generate bank reconciliation certificate · ${(bkAcct(gl) || {}).bank} · ${rmPeriodLabel(ym)}`, 'The certificate captures the BRS as of the period end and is routed to the Finance Manager and CFO for approval.', async r => { const asOf = ym === PROC_TODAY.slice(0, 7) ? PROC_TODAY : ym + '-31', R = bkBrs(gl, asOf, ym + '-01'); const tx = Store.clone(BKT()); tx.certificates.push({ id: 'C' + Date.now().toString(36), bank: gl, ym, preparedBy: App.user.name, at: nowIso(), book: R.book1, stmt: R.stmtBal, adj: R.adjBook, diff: R.diff, unm: R.unm.length, fm: null, cfo: null, status: 'Awaiting Finance Manager', reason: r }); fnNotify(fnFinUsers().filter(u => /Finance Manager|CFO/.test(u.role)).map(u => u.id), `Bank reconciliation certificate ${rmPeriodLabel(ym)} · ${(bkAcct(gl) || {}).bank} awaits approval`, '', 'br_reports'); await bkSaveAll(tx); audit('Bank Reconciliation', 'Reconciliation certificate generated', { new: `${gl} · ${ym} · difference ${INR(R.diff)}`, reason: r, approval: 'Awaiting Finance Manager' }); toast('Certificate generated.'); }); },
  bkCertSign: t => { const gl = bkGl(), ym = bkPeriodYm(), c = bkCertFor(gl, ym), who = t.dataset.k; if (!c) return; pcRemark(`Approve certificate as ${who === 'fm' ? 'Finance Manager' : 'CFO'}`, `${(bkAcct(gl) || {}).bank} · ${rmPeriodLabel(ym)} · difference ${INR(c.diff)}`, false, async rem => { const tx = Store.clone(BKT()), x = tx.certificates.find(y => y.id === c.id); x[who] = { by: App.user.name, at: nowIso(), remark: rem }; x.status = who === 'fm' ? 'Awaiting CFO' : 'Approved'; await bkSaveAll(tx); audit('Bank Reconciliation', `Certificate approved by ${who === 'fm' ? 'Finance Manager' : 'CFO'}`, { new: `${gl} · ${ym}`, reason: rem, approval: x.status, approver: App.user.name }); closeModal(); toast('Certificate ' + x.status.toLowerCase() + '.'); }); },
  /* bank feed / API configuration – tokens by reference only, never passwords or OTPs */
  bkFeedForm: t => { const gl = t.dataset.k, a = bkAcct(gl), P = bkProfile(a), F = (BKM().feeds || {})[gl] || { type: /API/.test(a.feed) ? 'API' : 'Manual', api: P.api, clientRef: '', tokenRef: '', sync: '06:00', status: /API/.test(a.feed) ? 'Connected (demo)' : 'Not connected', lastSync: '' }; modal(`${a.bank} · integration & import setup`, `<div class="note">Credentials are never stored here: only an approved token / client reference issued by ${esc(P.name)} is kept. Internet-banking passwords and OTPs must not be entered anywhere in the application.</div><div class="form-grid">${pcFld('Integration type', pcSel('bf_type', ['API', 'Manual'], F.type))}${pcFld('Bank API / feed', `<input id="bf_api" value="${esc(F.api || P.api)}">`)}${pcFld('Client / corporate ID reference', `<input id="bf_client" value="${esc(F.clientRef)}" placeholder="e.g. CORP-ID reference held by Treasury">`)}${pcFld('Approved token reference (masked)', `<input id="bf_token" value="${esc(F.tokenRef)}" placeholder="vault reference, not the token itself">`)}${pcFld('Daily sync time (IST)', `<input id="bf_sync" value="${esc(F.sync)}">`)}${pcFld('Status', pcSel('bf_status', ['Connected (demo)', 'Pending bank approval', 'Not connected'], F.status))}</div><p class="small">Manual download: ${esc(P.portal)}. Supported formats: ${P.formats.join(' · ')}. Column mapping is saved separately for this account after the first import.</p>`, `<button class="btn" data-act="closeModal">Cancel</button>${can('br_admin', 'Edit') || can('br_accounts', 'Edit') ? `<button class="btn primary" data-act="bkFeedOk" data-k="${gl}">Save</button>` : ''}`); },
  bkFeedOk: async t => { const gl = t.dataset.k, M = Store.clone(BKM()); M.feeds = M.feeds || {}; const old = M.feeds[gl]; const tok = (v('bf_token') || '').trim(); if (/^\d{4,8}$/.test(tok) || /password|otp/i.test(tok)) return toast('Enter a vault / token reference – not a password, OTP or raw token.', 'bad'); M.feeds[gl] = { type: v('bf_type'), api: v('bf_api'), clientRef: v('bf_client'), tokenRef: tok ? tok.replace(/.(?=.{4})/g, '•') : '', sync: v('bf_sync'), status: v('bf_status') }; const a = M.accounts.find(x => x.gl === gl); a.feed = v('bf_type') === 'API' ? `API feed (${v('bf_api')}) – daily ${v('bf_sync')}` : `Manual upload (${bkProfile(a).portal})`; await Store.put('bank', M); audit('Bank Reconciliation', 'Bank feed configuration changed', { old: old ? JSON.stringify(old) : '', new: JSON.stringify(M.feeds[gl]) }); closeModal(); toast('Integration saved.'); },
  bkImpTemplateBank: () => { if (!window.XLSX) return; const a = bkAcct(bkGl()), P = bkProfile(a); const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([P.template, ...P.sample]), 'Statement'); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Field', 'Column in ' + P.name + ' download'], ...Object.entries(P.aliases || {}).map(([k, alts]) => [k, alts.join(' / ')]), ['Date format', 'DD-MM-YYYY'], ['Amounts', 'INR, Indian grouping accepted (1,25,000.00)']]), 'Mapping'); saveFile(`MSEA_${P.code}_Statement_Template.xlsx`, new Blob([XLSX.write(wb, { bookType: 'xlsx', type: 'array' })])); }
});
